class Solution:
    def answerQueries(self, nums: list[int], queries: list[int]) -> list[int]:
        nums.sort()
        presum = [0]
        for num in nums:
            presum.append(presum[-1] + num)

        ans = []
        for query in queries:
            lo, hi = 0, len(presum) - 1
            idx = len(presum)
            while lo <= hi:
                mid = (lo + hi) // 2

                if presum[mid] > query:
                    idx = mid
                    hi = mid - 1
                else:
                    lo = mid + 1
            ans.append(idx - 1)

        return ans
